import { describe, expect, it } from 'vitest';
import { isBooleanLike, isIdentifierColumn, pickDefaultAxes, pickDefaultColorBy, valueIsTooRare, MIN_AGGREGATE_COUNT } from '../defaults';
import type { DataTable } from '../table';

const table = (columns: Record<string, any[]>): DataTable => ({
  columns: Object.keys(columns),
  data: columns,
  nRows: Object.values(columns)[0]?.length ?? 0,
});

describe('smart upload defaults', () => {
  it('recognizes explicit ID naming conventions without inferring from uniqueness', () => {
    expect(isIdentifierColumn('Id')).toBe(true);
    expect(isIdentifierColumn('participant_id')).toBe(true);
    expect(isIdentifierColumn('RecordID')).toBe(true);
    expect(isIdentifierColumn('valid')).toBe(false);
  });

  it('prefers measured variables and drops an ID rather than using it as Z', () => {
    const input = table({ Id: [1, 2, 3], Height: [160, 165, 170], Weight: [60, 66, 72] });
    expect(pickDefaultAxes(input)).toEqual({ x: 'Height', y: 'Weight', z: null });
  });

  it('keeps PC axes as the explicit projection default', () => {
    const input = table({ Id: [1, 2], PC1: [1, 2], PC2: [3, 4], PC3: [5, 6] });
    expect(pickDefaultAxes(input)).toEqual({ x: 'PC1', y: 'PC2', z: 'PC3' });
  });

  it('uses the lowest-cardinality non-boolean, non-ID grouping for colour', () => {
    const input = table({
      Id: [1, 2, 3, 4, 5, 6],
      is_complete: [1, 0, 1, 0, 1, 0],
      Species: ['setosa', 'setosa', 'versicolor', 'versicolor', 'virginica', 'virginica'],
      Batch: ['a', 'b', 'c', 'd', 'e', 'f'],
    });
    expect(isBooleanLike(input.data.is_complete)).toBe(true);
    expect(pickDefaultColorBy(input, '')).toBe('Species');
  });

  it('preserves a user-selected colour and falls back safely when no category exists', () => {
    const input = table({ Id: [1, 2, 3], Score: [10, 20, 30] });
    expect(pickDefaultColorBy(input, 'Score')).toBe('Score');
    expect(pickDefaultColorBy(input, '')).toBe('Score');
  });
});

// The assistant's privacy contract is "aggregates, never rows". The column
// profile it sends carries each categorical column's most frequent values —
// which on an email or free-text column is a handful of rows (finding D8).
//
// The test is per-VALUE rather than per-column on purpose. A column-level
// cardinality rule gets emails right and then withholds an ordinary 60-level
// `school` variable where every level covers 80 rows — a real loss of context
// for no privacy gain. What matters is how many people stand behind a value.
describe('valueIsTooRare — where naming a value stops being an aggregate', () => {
  it('withholds values covering too few rows to be a group', () => {
    expect(valueIsTooRare(1)).toBe(true);      // an email, a name, a free-text answer
    expect(valueIsTooRare(4)).toBe(true);
  });

  it('allows values that genuinely describe a group', () => {
    expect(valueIsTooRare(MIN_AGGREGATE_COUNT)).toBe(false);
    expect(valueIsTooRare(50)).toBe(false);    // Species in iris
    expect(valueIsTooRare(80)).toBe(false);    // one school among sixty
  });

  it('uses the conventional small-cell threshold', () => {
    expect(MIN_AGGREGATE_COUNT).toBe(5);
  });
});

// A bare /ID$/ matched any name ending in capital I-D, so ordinary variables
// were excluded from default axes and from the assistant's default PCA
// variables (finding E5).
describe('isIdentifierColumn — boundaries, not just suffixes', () => {
  it('still catches real identifier conventions', () => {
    for (const n of ['id', 'ID', 'Id', 'uuid', 'GUID', 'user_id', 'participant-id', 'subject id', 'respondentID', 'subjID']) {
      expect(isIdentifierColumn(n)).toBe(true);
    }
  });

  it('no longer swallows ordinary words ending in ID', () => {
    for (const n of ['VALID', 'HYBRID', 'RAPID', 'GRID', 'LIPID', 'ACID']) {
      expect(isIdentifierColumn(n)).toBe(false);
    }
  });

  it('leaves ordinary measures alone', () => {
    for (const n of ['score', 'age', 'PC1', 'openness_1', 'identity']) {
      expect(isIdentifierColumn(n)).toBe(false);
    }
  });
});

import { describe, it, expect } from 'vitest';
import { correlation, compareGroups, silhouetteByK, kDistancePercentiles } from '../stats';
import { dbscan, kmeans } from '../cluster';
import { sampleIndices } from '../random';

describe('correlation', () => {
  it('is +1 / -1 for perfectly linear data', () => {
    expect(correlation([1, 2, 3, 4, 5], [2, 4, 6, 8, 10]).pearson).toBeCloseTo(1, 9);
    expect(correlation([1, 2, 3, 4, 5], [10, 8, 6, 4, 2]).pearson).toBeCloseTo(-1, 9);
  });

  it('matches the hand-computed r = rho = 0.8 case', () => {
    const c = correlation([1, 2, 3, 4, 5], [1, 3, 2, 5, 4]);
    expect(c.pearson).toBeCloseTo(0.8, 9);
    expect(c.spearman).toBeCloseTo(0.8, 9);
    expect(c.n).toBe(5);
  });

  it('drops incomplete pairs (pairwise-complete)', () => {
    const c = correlation([1, 2, null, 4, 5, 'x' as any], [2, 4, 6, 8, 10, 12]);
    expect(c.n).toBe(4);
    expect(c.pearson).toBeCloseTo(1, 9);
  });
});

describe('compareGroups', () => {
  // A=[1,2,3] (mean 2), B=[5,6,7] (mean 6); SS_between=24, SS_total=28
  const g = compareGroups([1, 2, 3, 5, 6, 7], ['A', 'A', 'A', 'B', 'B', 'B']);

  it('sorts groups by mean, descending', () => {
    expect(g.groups[0].group).toBe('B');
    expect(g.groups[0].mean).toBeCloseTo(6, 9);
    expect(g.groups.map(x => x.n)).toEqual([3, 3]);
  });

  it('computes eta-squared and overall stats exactly', () => {
    expect(g.etaSquared).toBeCloseTo(24 / 28, 9);
    expect(g.overall.mean).toBeCloseTo(4, 9);
    expect(g.overall.n).toBe(6);
  });
});

describe('clustering diagnostics', () => {
  // two tight, far-apart blobs
  const blobA = Array.from({ length: 50 }, (_, i) => [0 + (i % 7) * 0.01, 0 + (i % 5) * 0.01]);
  const blobB = Array.from({ length: 50 }, (_, i) => [10 + (i % 7) * 0.01, 10 + (i % 5) * 0.01]);
  const pts = [...blobA, ...blobB];
  const colX = pts.map(p => p[0]);
  const colY = pts.map(p => p[1]);

  it('silhouette prefers k=2 for two clean blobs, with a high score', () => {
    const sil = silhouetteByK([colX, colY], kmeans as any, 5);
    const best = sil.reduce((a, b) => (b.silhouette > a.silhouette ? b : a));
    expect(best.k).toBe(2);
    expect(best.silhouette).toBeGreaterThan(0.8);
  });

  it('k-distance percentiles are positive and monotone', () => {
    const kd = kDistancePercentiles([colX, colY], 5)!;
    expect(kd.n).toBe(100);
    const p = kd.percentiles;
    expect(p.p50).toBeGreaterThan(0);
    expect(p.p50).toBeLessThanOrEqual(p.p75);
    expect(p.p75).toBeLessThanOrEqual(p.p90);
    expect(p.p90).toBeLessThanOrEqual(p.p95);
    expect(p.p95).toBeLessThanOrEqual(p.max);
  });
});

// The eps suggestion is only useful if the eps it names is the eps at which
// DBSCAN actually forms clusters. Nothing tied the two together before, which
// is how an off-by-one survived: the curve was read at the min_samples-th
// neighbour when min_samples counts the point itself, so every suggested eps
// was one neighbour too generous.
describe('kDistancePercentiles agrees with dbscan on what eps means', () => {
  // Unit-spaced 1-D lattice: an interior point has neighbours at 1, 2, 3, …
  // so for min_samples=3 (self + 2 others) the answer is exactly 1.0.
  const lattice = [Array.from({ length: 40 }, (_, i) => i)];

  it('reads the curve at the (min_samples - 1)-th neighbour', () => {
    expect(kDistancePercentiles(lattice, 3)!.kthNeighbor).toBe(2);
    expect(kDistancePercentiles(lattice, 3)!.percentiles.p50).toBeCloseTo(1, 9);
    expect(kDistancePercentiles(lattice, 4)!.percentiles.p50).toBeCloseTo(2, 9);
  });

  it('the suggested eps is one at which points really do become core points', () => {
    for (const minSamples of [3, 4, 5, 6]) {
      const eps = kDistancePercentiles(lattice, minSamples)!.percentiles.p50;
      // At that eps, at least half the points must be clustered rather than Noise
      const clustered = dbscan(lattice, eps, minSamples).filter(l => l !== 'Noise').length;
      expect(clustered).toBeGreaterThanOrEqual(lattice[0].length / 2);
      // ...and a hair under it must not be enough for the median point
      const below = dbscan(lattice, eps * 0.99, minSamples).filter(l => l !== 'Noise').length;
      expect(below).toBeLessThan(clustered);
    }
  });

  it('refuses min_samples below 2, where eps stops meaning anything', () => {
    expect(kDistancePercentiles(lattice, 1)).toBeNull();
    expect(kDistancePercentiles(lattice, 0)).toBeNull();
  });
});

describe('compareGroups — guarding a meaningless eta-squared (finding A7)', () => {
  it('reports the diagnostics a caller needs to refuse an identifier column', () => {
    const vals = Array.from({ length: 40 }, (_, i) => i * 1.7);
    const res = compareGroups(vals, vals.map((_, i) => `p${i}`));
    // eta-squared really is 1 here — the point is that the caller can now SEE why
    expect(res.etaSquared).toBeCloseTo(1, 12);
    expect(res.nGroups).toBe(40);
    expect(res.overall.n).toBe(40);
    expect(res.minGroupN).toBe(1);
    expect(res.singletonGroups).toBe(40);
  });

  it('omega-squared corrects the upward bias eta-squared carries', () => {
    // Many small groups drawn from ONE distribution: eta² is inflated by the
    // group count, omega² should sit near zero.
    let seed = 99;
    const rnd = () => (seed = (seed * 1664525 + 1013904223) % 4294967296) / 4294967296;
    const vals: number[] = [], grp: string[] = [];
    for (let g = 0; g < 25; g++) for (let i = 0; i < 3; i++) { vals.push(rnd()); grp.push(`g${g}`); }
    const res = compareGroups(vals, grp);
    expect(res.etaSquared!).toBeGreaterThan(0.3);        // inflated
    expect(res.omegaSquared!).toBeLessThan(res.etaSquared!);
    expect(Math.abs(res.omegaSquared!)).toBeLessThan(0.2); // near zero, correctly
  });

  it('agrees with eta-squared when groups are few and large', () => {
    const a = Array.from({ length: 200 }, (_, i) => (i % 2 ? 10 : 0) + (i % 7) * 0.1);
    const g = a.map((_, i) => (i % 2 ? 'B' : 'A'));
    const res = compareGroups(a, g);
    expect(res.nGroups).toBe(2);
    expect(res.minGroupN).toBe(100);
    expect(res.singletonGroups).toBe(0);
    expect(Math.abs(res.etaSquared! - res.omegaSquared!)).toBeLessThan(0.01);
  });
});

describe('toMatrix sampling is seeded and random, not strided (finding A4)', () => {
  // Periodic data: a stride equal to the period samples ONE stratum. 4800 rows
  // with a 1200 cap gives stride exactly 4, which is the pathological case.
  // Four separated strata (wave 0..3, values around 0/100/200/300), every row a
  // distinct point so nearest-neighbour distances are never degenerate.
  const n = 4800;
  const wave = Array.from({ length: n }, (_, i) => i % 4);
  const value = Array.from({ length: n }, (_, i) => (i % 4) * 100 + Math.floor(i / 4) * 0.01);

  it('sees every stratum rather than one', () => {
    // A stride of 4 lands on one wave, so the sample would carry a single value
    // of `wave` and the k-distance curve would describe that stratum alone.
    const picked = sampleIndices(n, 2000);
    expect(picked.length).toBe(2000);
    expect(new Set(picked.map(i => wave[i])).size).toBe(4);
    expect(new Set(picked).size).toBe(2000);          // no duplicates
    expect(picked.some(i => i % 4 !== 0)).toBe(true);  // not the strided sample

    const kd = kDistancePercentiles([value, wave], 5)!;
    expect(kd.n).toBe(2000);
    expect(kd.percentiles.p95).toBeGreaterThan(0);
  });

  it('is reproducible across calls', () => {
    const a = kDistancePercentiles([value, wave], 5)!;
    const b = kDistancePercentiles([value, wave], 5)!;
    expect(a.percentiles).toEqual(b.percentiles);
  });
});

import type OpenAIType from 'openai';
