export const toolsFor = (policy: DataPolicy): ChatCompletionTool[] =>
  policy.rowAccess ? [...BASE_TOOLS, ...EFA_TOOLS, ...OPEN_TOOLS] : [...BASE_TOOLS, ...EFA_TOOLS];

// The conversation-level policy: open only when every loaded dataset is open.
export const sessionPolicyOf = (state: ReturnType<AppBridge['getState']>): DataPolicy =>
  combinedPolicy(state.datasets.map(d => d.dataMode));

const fmtNum = (v: number | undefined) =>
  v === undefined ? '?' : Math.abs(v) >= 100 ? v.toFixed(0) : String(Math.round(v * 100) / 100);

export const buildSystemPrompt = (bridge: AppBridge): string => {
  const s = bridge.getState();
  const policy = sessionPolicyOf(s);
  const anyOpen = s.datasets.some(d => d.dataMode === 'open');
  // Three access postures, one paragraph each — the paragraph MUST match the
  // tool list toolsFor() built from the same policy, so both derive from it.
  const accessParagraph = policy.rowAccess
    ? `Every loaded dataset was explicitly declared public/open by the user. In addition to aggregate statistics you may inspect raw data: sample_rows (seeded random sample or top-N by a column), get_rows_where (filtered rows), and list_categories (full value counts, including single-row values). Each call returns at most ${MAX_SAMPLE_ROWS} rows — a token budget, not a privacy rule. Still prefer aggregates first: pull rows to verify anomalies, inspect outliers or specific cases, or answer questions the summaries cannot.`
    : `You see column metadata and aggregate statistics only; you never see raw data rows. Numeric columns come as mean/sd/quartiles, plus min and max only when at least 5 rows share that extreme (tailsWithheld marks a column whose extreme belonged to too few people to report) — use the quartiles to notice skew and ceiling effects rather than asking for the data. Group statistics (compare_groups, cluster breakdowns, tests, charts) list only groups of at least 5 rows; the rest are pooled or omitted unnamed. Categorical columns list only values covering at least 5 rows; rareValuesWithheld counts the distinct values held back for being rarer than that, and identifier-like columns list none at all. That is a privacy guarantee, not a gap to work around: never ask the user to paste rows, and if asked about an individual row or participant, explain that you only have access to summaries.${anyOpen ? ' (Some loaded datasets are marked open, but at least one is private, so the whole conversation runs at the private level — row tools are unavailable until every loaded dataset is open.)' : ''}`;
  const cols = s.columns
    .map(c =>
      c.kind === 'numeric'
        ? `- ${c.name}: numeric, ${fmtNum(c.min)}–${fmtNum(c.max)}${c.missing ? `, ${c.missing} missing` : ''}`
        : `- ${c.name}: categorical (${c.nUnique} values: ${(c.topCategories ?? [])
            .slice(0, 6)
            .map(t => `${t.value} n=${t.count}`)
            .join(', ')})${c.missing ? `, ${c.missing} missing` : ''}`
    )
    .join('\n');

  return `You are the built-in assistant of Scatter Lab, a browser-based workbench where researchers explore tabular data as interactive 2D/3D scatter plots, project data through PCA components, run DBSCAN/K-Means clustering, and compare pinned views. The user is typically a survey researcher.

You can drive the app with your tools: change plot axes, coloring and marker shape, switch 2D/3D or the active dataset, run clustering, read cluster compositions, configure and save a cluster-composition heatmap, save PNG, interactive HTML, rotating GIF, or active-dataset CSV exports, mute/hide legend categories, transfer columns between datasets, pin/remove views, and save workspaces. You also have aggregate analysis tools: run_pca (in-browser principal component analysis — use it when the user wants to reduce dimensions or "see the structure" of a set of scale items; it reports how much data was imputed or dropped, which you should mention when it is not negligible), correlate (Pearson/Spearman), compare_groups (means by category + eta-squared), run_test (Welch's t, Mann–Whitney, Kruskal–Wallis, Kolmogorov–Smirnov, chi-square — exact p, CI, effect size), plot_chart (ECDF, histogram, box, violin, Q–Q, bar, line — rendered for the user as analysis views), and clustering diagnostics (suggest_k silhouette scores, suggest_eps k-distance percentiles) — prefer running these over guessing parameters or relationships. run_test and plot_chart take a PLAN that a deterministic validator gates: on rejection, revise using the [code]/Fix/Available in the result and call again — after ${MAX_PLAN_REVISIONS} rejected revisions, stop and put the failures to the user. Report exact p-values with the effect size and CI; never add significance stars. Use tools to act, then summarize what you did in one or two sentences. When the user asks a question about their data, answer from the column profiles and aggregate tool results — never invent numbers you have not seen in this conversation.

Ordinal EFA has its own workflow alongside PCA. Use list_efa_runs, get_efa_diagnostics and paginated get_efa_items to inspect saved fits; never invent loadings. Distinguish pattern coefficients, structure correlations, communalities and uniquenesses. Use update_efa_items for visible review statuses/notes, then refit_efa_selection for a new child and efa_job to poll. Read the current reviewRevision first; a conflict means reread. Explain substantive coverage, cross-loadings and redundancy together; there is no universally optimal item set or additive PCA-style variance breakdown for correlated factors. compare_efa aligns factors by signs/permutation. MICE summaries describe between-imputation dispersion and do not provide Rubin-pooled inference; individual WLSMV SEs belong to separate fits. Holdout comparison is structure replication, not proof of validity. Add scores only through the explicit add_efa_scores action. Large simulations and WLSMV can take time; report the job state accurately.

${accessParagraph}

Facts about THIS app that you cannot guess and are likely to get wrong from priors — state them when they come up, without needing to look them up:
- K-Means here is DETERMINISTIC. It is seeded k-means++ from fixed seeds, best of 10 initialisations, up to 300 iterations, so the same data and the same k always give identical clusters. The usual answer ("no, k-means is randomly initialised") is wrong for this app. Say so, and add that reproducibility is not evidence of stable structure — to test that, vary k and re-run on subsamples.
- Missing values in CLUSTERING are always median-imputed. In PCA the user chooses: median, regularized iterative PCA (missMDA imputePCA), or complete-case. Every run reports how many cells it filled or how many rows it dropped, and in which variables.
- Clustering runs on the two or three columns currently on the X, Y and Z axes — nothing else. Choosing the axes IS choosing the features. Good for PC scores, weak for two arbitrary raw columns.
- compare_groups reports SAMPLE standard deviations (n-1), the reporting convention; the PCA and projection use population (÷n) internally to match scikit-learn. eta-squared is reported alongside omega-squared, which corrects its upward bias — prefer omega-squared when there are many groups.
- suggest_eps reads the k-distance curve at the (min_samples - 1)-th neighbour, because dbscan counts the point itself toward min_samples. eps is in the units of the plotted axes, or in standard deviations when standardize is on.

Statistical guidance is welcome: help interpret PC loadings, choose sensible eps/min_samples or k, and reason about what cluster compositions suggest — while being clear about the limits of exploratory clustering (results depend on parameters; clusters are descriptive, not proof of latent groups).

When the user asks you to interpret results or asks a methods question (components to keep, whether clusters are meaningful, effect sizes, correlations), call get_methods_reference first and ground your answer in the returned text, mentioning the sources it names. Keep the interpretation tied to their actual numbers.

When explaining where something is in the interface or how to do something manually, call highlight_ui to point an ephemeral highlight at the relevant control while you explain — especially during tours (pair each tour step with its highlight).

Tours: when the user asks for a tour, asks how the app works, or seems new, call get_tutorial and teach from it — never invent UI details. For a demo of the built-in Iris data, request the iris_demo topic first: a scripted click-through walkthrough already exists in the panel menu, and pointing them at it is better than narrating your own. Only run a tour yourself if they decline it, or if they want their own data toured. When you do, pause after each beat with a concrete “Ready to continue to [next step]?” question, never an unstructured “what next?” that loses the tour. For a general tour, pick the sections that match their situation (no data yet → start with load_data). Do not initiate any download just because it is part of a tour: offer it, then wait for a clear user yes.

Keep responses short and concrete. This is a side panel, not a report.

Current session:
${s.datasets.length === 0 ? 'No dataset loaded yet — suggest loading one (there is a demo dataset button on the empty canvas).' : `Data access: ${policy.rowAccess ? 'OPEN — row tools available' : 'PRIVATE — aggregates only'}.
Datasets: ${s.datasets.map(d => `${d.name} (${d.nRows} rows, ${d.dataMode}${d.active ? ', active' : ''})`).join('; ')}
Plot: ${s.viewMode}, x=${s.axes.x}, y=${s.axes.y}${s.axes.z ? `, z=${s.axes.z}` : ''}, colored by ${s.colorBy}${s.shapeBy ? `, marker shape by ${s.shapeBy}` : ''}. Pinned views: ${s.pinnedViews}/3.
Columns of the active dataset:
${cols}`}`;
};

export type StreamHandlers = {
  onText: (delta: string) => void;
  onToolUse: (name: string, argsSummary?: string) => void;
};

// Compact "k=v" rendering of tool arguments for the chat's tool chips
export const summarizeArgs = (argsJson: string): string => {
  try {
    const o = JSON.parse(argsJson || '{}');
    const s = Object.entries(o)
      .map(([k, v]) => `${k}=${Array.isArray(v) ? v.join('|') : String(v)}`)
      .join(' ');
    return s.length > 70 ? s.slice(0, 67) + '…' : s;
  } catch {
    return '';
  }
};

const makeClient = async (apiKey: string, baseURL: string) => {
  const OpenAI = await loadOpenAI();
  return new OpenAI({
    apiKey,
    baseURL,
    dangerouslyAllowBrowser: true,
    maxRetries: 1,
    defaultHeaders: {
      'HTTP-Referer': 'https://scatter-lab.vercel.app',
      'X-Title': 'Scatter Lab',
    },
  });
};

// One user turn: stream the response, execute any tool calls, loop until the
// model stops asking for tools. Returns the updated history.
// Yield until React has committed and painted.
//
// Anything making two bridge calls in a row needs this: the second call
// otherwise reads state from before the first one's commit. A fixed timeout
// proved too short on slow machines. Exported because the scripted walkthrough
// runs multi-call steps and must not grow its own copy of the rule.
export const paintYield = (): Promise<void> =>
  new Promise<void>(resolve => {
    if (typeof requestAnimationFrame === 'undefined') return void setTimeout(resolve, 50);
    requestAnimationFrame(() => requestAnimationFrame(() => setTimeout(resolve, 20)));
  });

// The transport seam: one model round-trip, from messages+tools to the
// assistant's reply. runAssistantTurn owns the LOOP (execute tools, feed
// results back, stop when no tools are called); the transport owns only the
// wire. The default is the streaming OpenAI client below; the replay harness
// (replay.ts) substitutes a scripted transport, which is what lets every
// assistant avenue run deterministically in vitest with no key and no network.
export type ModelToolCall = { id: string; name: string; arguments: string };
export type ModelTurn = { content: string; toolCalls: ModelToolCall[] };
export type ModelRequest = {
  model: string;
  messages: ChatCompletionMessageParam[];
  tools: ChatCompletionTool[];
  onText: (delta: string) => void;
};
export type ModelTransport = (req: ModelRequest) => Promise<ModelTurn>;

const openAITransport = async (apiKey: string, baseURL: string): Promise<ModelTransport> => {
  const client = await makeClient(apiKey, baseURL);
  return async ({ model, messages, tools, onText }) => {
    const stream = client.chat.completions.stream({ model, max_tokens: 4096, messages, tools });
    stream.on('content', delta => onText(delta));
    const completion = await stream.finalChatCompletion();
    const choice = completion.choices[0];
    if (!choice) throw new Error('Empty response from the model.');
    return {
      content: choice.message.content ?? '',
      toolCalls: (choice.message.tool_calls ?? [])
        .filter(c => c.type === 'function')
        .map(c => ({ id: c.id, name: c.function.name, arguments: c.function.arguments })),
    };
  };
};

export const runAssistantTurn = async (
  apiKey: string,
  baseURL: string,
  model: string,
  history: ChatCompletionMessageParam[],
  userText: string,
  // The REF, not the bridge object: React reassigns .current with fresh
  // closures on every commit, so each tool call sees post-commit state.
  // (Passing the object froze the whole turn at send-time state.)
  bridgeRef: { current: AppBridge },
  handlers: StreamHandlers,
  // Tests inject a scripted transport; the app omits this and gets the wire.
  transport?: ModelTransport,
): Promise<ChatCompletionMessageParam[]> => {
  const send = transport ?? (await openAITransport(apiKey, baseURL));
  const messages: ChatCompletionMessageParam[] = [...history, { role: 'user', content: userText }];

  // The revision cap, enforced rather than merely prompted: after
  // MAX_PLAN_REVISIONS rejected plans in ONE user turn, further rejections
  // tell the model to stop retrying and put the failures to the user.
  let planRejections = 0;
  const countRejection = (result: string): string => {
    if (!result.startsWith('Plan rejected')) return result;
    planRejections++;
    return planRejections > MAX_PLAN_REVISIONS
      ? `${result}\n[Revision limit reached (${MAX_PLAN_REVISIONS}): do NOT retry. Summarize these failures for the user and ask how to proceed.]`
      : result;
  };

  const executeTool = async (name: string, argsJson: string): Promise<string> => {
    const bridge = bridgeRef.current; // fresh closures as of the latest commit
    let input: any = {};
    try {
      input = argsJson ? JSON.parse(argsJson) : {};
    } catch {
      return 'Tool error: arguments were not valid JSON.';
    }
    try {
      switch (name) {
        case 'get_app_state':
          return JSON.stringify(bridge.getState());
        case 'set_plot':
          return bridge.setPlot(input ?? {});
        case 'run_clustering':
          return bridge.runClustering(input.method, input);
        case 'get_cluster_breakdown':
          return bridge.getClusterBreakdown(input.attribute);
        case 'save_cluster_heatmap':
          return await bridge.saveClusterHeatmap(input);
        case 'save_rotating_gif':
          return await bridge.saveRotatingGif();
        case 'save_active_view_png':
          return await bridge.saveActiveViewPng();
        case 'save_interactive_html':
          return await bridge.saveInteractiveHtml();
        case 'save_active_dataset_csv':
          return bridge.saveActiveDatasetCsv();
        case 'pin_view':
          return bridge.pinView();
        case 'get_tutorial': {
          const topics: string[] = Array.isArray(input?.topics) && input.topics.length ? input.topics : TUTORIAL_TOPICS;
          return topics
            .filter(t => TUTORIAL[t])
            .map(t => `## ${t}\n${TUTORIAL[t]}`)
            .join('\n\n') || `Unknown topics. Available: ${TUTORIAL_TOPICS.join(', ')}.`;
        }
        case 'load_demo_data':
          return await bridge.loadDemoData();
        case 'run_pca':
          return bridge.runPCA(input ?? {});
        case 'list_efa_runs':
        case 'get_efa_items':
        case 'update_efa_items':
        case 'refit_efa_selection':
        case 'run_efa':
        case 'efa_job':
        case 'get_efa_diagnostics':
        case 'compare_efa':
        case 'add_efa_scores':
        case 'parallel_efa':
          return bridge.efa ? await bridge.efa(name, input ?? {}) : 'EFA is unavailable in this session.';
        case 'correlate':
          return bridge.correlate(input.col_a, input.col_b);
        case 'compare_groups':
          return bridge.compareGroups(input.numeric_col, input.group_col);
        case 'run_test':
          return countRejection(bridge.runTest({
            kind: 'test', test: input.test, column: input.column,
            groupBy: input.group_by, ...(input.groups !== undefined ? { groups: input.groups } : {}),
          }));
        case 'plot_chart':
          return countRejection(bridge.plotChart({
            kind: 'chart', mark: input.mark, column: input.column,
            ...(input.group_by !== undefined ? { groupBy: input.group_by } : {}),
            ...(input.orientation !== undefined ? { orientation: input.orientation } : {}),
            ...(input.x !== undefined ? { x: input.x } : {}),
            ...(input.agg !== undefined ? { agg: input.agg } : {}),
            ...(input.bins !== undefined ? { bins: input.bins } : {}),
          }));
        case 'suggest_k':
          return bridge.suggestK(Math.min(input?.max_k ?? 8, 12), input?.standardize);
        case 'suggest_eps':
          return bridge.suggestEps(input?.min_samples, input?.standardize);
        case 'switch_dataset':
          return bridge.switchDataset(input.name);
        case 'set_category_visibility':
          return bridge.setCategoryVisibility(input.categories ?? [], input.state);
        case 'set_row_filter':
          return bridge.setRowFilter(input ?? {});
        case 'transfer_column':
          return bridge.transferColumn(input);
        case 'remove_pin':
          return bridge.removePin(input.index);
        case 'save_workspace':
          return await bridge.saveWorkspaceAs(input.name);
        case 'get_methods_reference': {
          const chunks = searchMethods({ topics: input?.topics, query: input?.query });
          if (!chunks.length) return `Nothing matched. Available topics: ${METHODS_TOPICS.join(', ')}.`;
          return chunks.map(c => `## ${c.title}\n${c.text}`).join('\n\n');
        }
        case 'sample_rows':
          return bridge.sampleRows?.(input ?? {}) ?? 'Row access is not available: the session is in Private data mode.';
        case 'get_rows_where':
          return bridge.getRowsWhere?.(input) ?? 'Row access is not available: the session is in Private data mode.';
        case 'list_categories':
          return bridge.listCategories?.(input.column) ?? 'Row access is not available: the session is in Private data mode.';
        case 'control_view':
          return bridge.controlView(input ?? {});
        case 'highlight_ui':
          return bridge.highlightUI(input.target);
        default:
          return `Unknown tool: ${name}`;
      }
    } catch (err: any) {
      return `Tool error: ${err?.message ?? err}`;
    }
  };

  const MAX_LOOPS = 16;
  for (let i = 0; i < MAX_LOOPS; i++) {
    const turn = await send({
      model,
      messages: [
        { role: 'system', content: buildSystemPrompt(bridgeRef.current) },
        ...messages,
      ],
      // Recomputed each iteration: a tool call this loop already ran (e.g.
      // switch_dataset) can change which datasets — and so which mode — the
      // next iteration is talking about.
      tools: toolsFor(sessionPolicyOf(bridgeRef.current.getState())),
      onText: handlers.onText,
    });

    // Keep the assistant turn (content and/or tool_calls) in history
    messages.push({
      role: 'assistant',
      content: turn.content,
      ...(turn.toolCalls.length
        ? {
            tool_calls: turn.toolCalls.map(c => ({
              id: c.id, type: 'function' as const,
              function: { name: c.name, arguments: c.arguments },
            })),
          }
        : {}),
    } as ChatCompletionMessageParam);

    if (!turn.toolCalls.length) return messages;

    for (const call of turn.toolCalls) {
      handlers.onToolUse(call.name, summarizeArgs(call.arguments));
      messages.push({
        role: 'tool',
        tool_call_id: call.id,
        content: await executeTool(call.name, call.arguments),
      });
      await paintYield();
    }
  }
  handlers.onText('\n[Paused after many tool calls — say "continue" to keep going.]');
  return messages;
};

export type ModelInfo = { id: string; created: number };

// Fetch the model catalog from the endpoint (OpenRouter serves this publicly).
// Returns [] on failure — the panel falls back to a free-text model field.
export const fetchModels = async (baseURL: string, apiKey: string): Promise<ModelInfo[]> => {
  try {
    const res = await fetch(`${baseURL.replace(/\/$/, '')}/models`, {
      headers: apiKey ? { Authorization: `Bearer ${apiKey}` } : {},
    });
    if (!res.ok) return [];
    const data = await res.json();
    const list: any[] = data?.data ?? [];
    // OpenRouter reports supported_parameters per model; only models that
    // support tool calling can drive the app. Endpoints without capability
    // info (e.g. local runtimes) are left unfiltered.
    const hasCaps = list.some(m => Array.isArray(m?.supported_parameters));
    return list
      .filter(m => !hasCaps || (Array.isArray(m?.supported_parameters) && m.supported_parameters.includes('tools')))
      .filter(m => typeof m?.id === 'string')
      .map(m => ({ id: m.id as string, created: typeof m?.created === 'number' ? m.created : 0 }))
      .sort((a, b) => a.id.localeCompare(b.id));
  } catch {
    return [];
  }
};

// Curated suggestions: the newest tool-capable model from each major family
// actually present in the live catalog — so we never suggest a stale ID.
const SUGGESTED_FAMILIES = [
  'anthropic/claude', 'openai/gpt', 'google/gemini',
  'x-ai/grok', 'deepseek/deepseek', 'qwen/qwen',
];
export const suggestModels = (models: ModelInfo[]): string[] => {
  const out: string[] = [];
  for (const fam of SUGGESTED_FAMILIES) {
    const candidates = models
      .filter(m => m.id.startsWith(fam) && !m.id.includes(':free') && !/preview|exp/.test(m.id))
      .sort((a, b) => b.created - a.created);
    // Prefer the newest full-strength model; speed tiers only as fallback
    const best = candidates.find(m => !/fast|flash|mini|lite|nano|tiny|air/.test(m.id)) ?? candidates[0];
    if (best) out.push(best.id);
  }
  return out;
};

// Friendly error strings for the panel
export const describeApiError = (err: unknown): string => {
  // Reads err.status rather than `instanceof OpenAI.AuthenticationError`, so
  // this stays synchronous and does not force the SDK to be loaded just to
  // describe a failure (F1). The status codes are the same contract the error
  // classes wrap, and they survive a client that never loaded at all.
  const e = err as { status?: number; message?: string; name?: string };
  switch (e?.status) {
    case 401:
    case 403: return 'API key rejected — check it in settings.';
    case 404: return 'Model not found — check the model ID in settings.';
    case 429: return 'Rate limited — wait a moment and try again.';
  }
  // APIConnectionError carries no status: the request never reached a server.
  if (e?.name === 'APIConnectionError' || e?.name === 'APIConnectionTimeoutError') {
    return 'Could not reach the API — check your connection.';
  }
  if (typeof e?.status === 'number') return `API error: ${e.message ?? e.status}`;
  return `Error: ${e?.message ?? err}`;
};

// Assistant feedback: thumbs up/down per assistant message, with an optional
// free-text reason. Records go to a Supabase table whose anon key is
// insert-only (RLS) — the app can file feedback but never read it back.
//
// Writes are buffered in IndexedDB and flushed in the background, so a click
// is never lost to a network blip. Delivery is AT-LEAST-ONCE: a tab can close
// between a successful POST and the queue delete, and two open tabs mount-flush
// the same shared queue concurrently. Both used to produce visible duplicates
// in the insert-only table. Every record therefore carries a `client_key` that
// the table unique-indexes (migration 20260802000000_feedback_idempotency):
// redelivery is a server-side no-op. A Web Lock serializes flushes across tabs
// as well, so the common case never even re-sends.
//
// When Supabase isn't configured (env vars unset), the feedback UI stays
// hidden entirely.

export type FeedbackRecord = {
  event_id: string;
  rating: 'up' | 'down';
  reason?: string | null;
  model?: string;
  tools?: string[];
  user_message?: string | null;
  assistant_message?: string | null;
  /** Idempotency key, stamped once at enqueue. Unique-indexed server-side. */
  client_key?: string;
};

/** What sits in the IndexedDB queue. Entries buffered by older builds are bare
 *  FeedbackRecords; normalizeEntry upgrades them on read. */
type QueuedEntry = { rec: FeedbackRecord; attempts: number };

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL ?? '';
const SUPABASE_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ?? '';

// A row rejected this many times (responses received, not network failures) is
// dropped — one poison row must not wedge everything queued behind it forever.
const MAX_ATTEMPTS = 5;

export const feedbackEnabled = (): boolean =>
  SUPABASE_URL.startsWith('https://') && SUPABASE_KEY.length > 20;

// --- IndexedDB buffer -------------------------------------------------------

const DB_NAME = 'scatter-lab-feedback';
const STORE = 'queue';

const openDB = (): Promise<IDBDatabase> =>
  new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = () => {
      if (!req.result.objectStoreNames.contains(STORE)) {
        req.result.createObjectStore(STORE, { autoIncrement: true });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });

const normalizeEntry = (v: QueuedEntry | FeedbackRecord): QueuedEntry =>
  'rec' in v ? (v as QueuedEntry) : { rec: v as FeedbackRecord, attempts: 0 };

const enqueue = async (rec: FeedbackRecord): Promise<void> => {
  const db = await openDB();
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(STORE, 'readwrite');
    tx.objectStore(STORE).add({ rec, attempts: 0 } satisfies QueuedEntry);
    tx.oncomplete = () => { db.close(); resolve(); };
    tx.onerror = () => { db.close(); reject(tx.error); };
  });
};

const drainQueue = async (): Promise<{ key: IDBValidKey; entry: QueuedEntry }[]> => {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE, 'readonly');
    const store = tx.objectStore(STORE);
    const keysReq = store.getAllKeys();
    const valsReq = store.getAll();
    tx.oncomplete = () => {
      db.close();
      resolve(keysReq.result.map((key, i) => ({ key, entry: normalizeEntry(valsReq.result[i]) })));
    };
    tx.onerror = () => { db.close(); reject(tx.error); };
  });
};

const removeFromQueue = async (keys: IDBValidKey[]): Promise<void> => {
  if (!keys.length) return;
  const db = await openDB();
  await new Promise<void>((resolve) => {
    const tx = db.transaction(STORE, 'readwrite');
    for (const k of keys) tx.objectStore(STORE).delete(k);
    tx.oncomplete = () => { db.close(); resolve(); };
    tx.onerror = () => { db.close(); resolve(); };
  });
};

const updateEntry = async (key: IDBValidKey, entry: QueuedEntry): Promise<void> => {
  const db = await openDB();
  await new Promise<void>((resolve) => {
    const tx = db.transaction(STORE, 'readwrite');
    tx.objectStore(STORE).put(entry, key);
    tx.oncomplete = () => { db.close(); resolve(); };
    tx.onerror = () => { db.close(); resolve(); };
  });
};

// --- Supabase REST insert ---------------------------------------------------

// 'ok'       — inserted (or already present; duplicates resolve to no-ops)
// 'rejected' — the server answered and said no; retrying identical bytes won't help
// 'network'  — nothing answered; the row stays queued and costs no attempt
type PostResult = 'ok' | 'rejected' | 'network';

const postRows = async (
  rows: FeedbackRecord[],
  opts: { keepalive?: boolean; onConflict?: boolean } = {}
): Promise<PostResult> => {
  const { keepalive = false, onConflict = true } = opts;
  const base = `${SUPABASE_URL.replace(/\/$/, '')}/rest/v1/assistant_feedback`;
  try {
    const res = await fetch(onConflict ? `${base}?on_conflict=client_key` : base, {
      method: 'POST',
      keepalive,
      headers: {
        'Content-Type': 'application/json',
        apikey: SUPABASE_KEY,
        Authorization: `Bearer ${SUPABASE_KEY}`,
        Prefer: onConflict ? 'return=minimal,resolution=ignore-duplicates' : 'return=minimal',
      },
      body: JSON.stringify(rows),
    });
    return res.ok ? 'ok' : 'rejected';
  } catch {
    return 'network';
  }
};

// --- Flush ------------------------------------------------------------------

const flushOnce = async (keepalive: boolean): Promise<void> => {
  const pending = await drainQueue();
  if (!pending.length) return;

  const batch = await postRows(pending.map((p) => p.entry.rec), { keepalive });
  if (batch === 'ok') {
    await removeFromQueue(pending.map((p) => p.key));
    return;
  }
  if (batch === 'network') return; // offline — everything stays queued, no attempts burned

  // The server rejected the batch. Retry per row so one poison row can't wedge
  // the rest, with a one-time bridge for servers that predate the client_key
  // migration (on_conflict against a missing index is itself a 4xx).
  for (const { key, entry } of pending) {
    let result = await postRows([entry.rec], { keepalive });
    if (result === 'rejected') {
      // Pre-migration bridge: that server lacks the client_key COLUMN too, and
      // PostgREST rejects unknown body keys — so the key must leave the body,
      // not just the on_conflict param. Costs idempotency for this one delivery,
      // which is the documented pre-migration trade-off.
      const { client_key: _omit, ...legacy } = entry.rec;
      result = await postRows([legacy], { keepalive, onConflict: false });
    }
    if (result === 'ok') {
      await removeFromQueue([key]);
    } else if (result === 'rejected') {
      const attempts = entry.attempts + 1;
      if (attempts >= MAX_ATTEMPTS) {
        console.warn('[feedback] dropping row after repeated server rejections:', entry.rec.event_id);
        await removeFromQueue([key]);
      } else {
        await updateEntry(key, { ...entry, attempts });
      }
    }
    // 'network': leave as-is; the next flush retries from the top
  }
};

let flushing = false;
export const flushFeedback = async (opts: { keepalive?: boolean } = {}): Promise<void> => {
  if (!feedbackEnabled() || flushing) return;
  flushing = true;
  try {
    // The queue is shared across tabs but `flushing` isn't — without the lock,
    // two tabs mount-flushing together both drain the same rows and double-post
    // them. The lock serializes; client_key makes any survivor harmless anyway.
    if (typeof navigator !== 'undefined' && navigator.locks) {
      await navigator.locks.request('scatter-lab-feedback-flush', () => flushOnce(opts.keepalive ?? false));
    } else {
      await flushOnce(opts.keepalive ?? false);
    }
  } catch { /* stays queued for the next flush */ } finally {
    flushing = false;
  }
};

// Queue then flush — the record is durable the moment this resolves
export const submitFeedback = async (rec: FeedbackRecord): Promise<void> => {
  await enqueue({ ...rec, client_key: rec.client_key ?? crypto.randomUUID() });
  void flushFeedback();
};

// A record queued moments before the tab closes would otherwise wait for the
// NEXT session's mount flush (possibly days). keepalive lets the request
// outlive the page.
if (typeof window !== 'undefined') {
  window.addEventListener('pagehide', () => { void flushFeedback({ keepalive: true }); });
}

import Papa from 'papaparse';
import { DataTable, rowsToTable } from './table';
// Types only — importing the worker module for its values would pull SheetJS
// back into the page bundle and undo the isolation it exists to provide.
import type { SheetInfo, WorkbookExtract, XlsxRequest, XlsxResponse } from './xlsx.worker';

export type { SheetInfo };

export const SUPPORTED_EXTENSIONS = ['.csv', '.xlsx', '.parquet'];

// Nothing bounded input size, and parsing a CSV still happens on the main
// thread, so a large file froze the tab on "Processing…" with no explanation
// and no way to cancel (finding C9).
//
// The hard limit is set where the browser would fail anyway: the whole table is
// held in memory as columnar arrays, and a text file becomes several times its
// own size as JS values, so a quarter-gigabyte input is already past what a tab
// can hold alongside a WebGL plot. Refusing with a number beats an OOM crash
// that looks like a bug in the app.
export const MAX_FILE_BYTES = 250 * 1024 * 1024;
// Below the hard limit but big enough that the wait needs explaining.
export const LARGE_FILE_BYTES = 25 * 1024 * 1024;

const formatBytes = (b: number) =>
  b >= 1024 * 1024 * 1024 ? `${(b / 1024 / 1024 / 1024).toFixed(1)} GB` : `${Math.round(b / 1024 / 1024)} MB`;

// Parsers report what they silently did to the file alongside the table.
// PapaParse hands back a res.errors array describing ragged rows, unterminated
// quotes and undetectable delimiters; ignoring it meant a malformed CSV loaded
// as a plausible-looking table with rows quietly dropped or nulled. Anything
// that changes what the user's data means belongs in here.
export type ParsedTable = { table: DataTable; warnings: string[] };

const plural = (n: number, one: string, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;
const listRows = (rowIdx: number[]) => {
  // PapaParse row indices are 0-based over data rows; +2 to name the file line
  const lines = rowIdx.slice(0, 3).map(r => r + 2);
  return lines.join(', ') + (rowIdx.length > 3 ? `, …` : '');
};

// A column that arrived entirely as strings may be numbers written in a format
// dynamicTyping does not recognise. Worth naming precisely, because the
// downstream symptom ("needs at least two numeric columns") points elsewhere.
// Order matters: "1,234" satisfies both readings, so the stricter grouped form
// (exactly three digits after each comma) is tested first.
const NUMERIC_TEXT_PATTERNS: { test: RegExp; label: string; hint: string }[] = [
  {
    test: /^-?\d{1,3}(,\d{3})+(\.\d+)?$/,
    label: 'thousands separators',
    hint: 'Remove the thousands separators so the values parse as numbers.',
  },
  {
    test: /^-?\d+,\d+$/,
    label: 'decimal commas',
    hint: 'Save the file with a period as the decimal separator, or convert those columns before uploading.',
  },
  {
    test: /^-?[\d.]+\s*%$/,
    label: 'percent signs',
    hint: 'Strip the % and store the value as a number.',
  },
];

const numericTextWarnings = (table: DataTable): string[] => {
  const found = new Map<string, string[]>();
  for (const col of table.columns) {
    const vals = (table.data[col] ?? []).filter(v => v != null);
    if (!vals.length || vals.some(v => typeof v === 'number')) continue;
    for (const { test, label } of NUMERIC_TEXT_PATTERNS) {
      const hits = vals.filter(v => typeof v === 'string' && test.test(v.trim())).length;
      if (hits / vals.length >= 0.8) {
        if (!found.has(label)) found.set(label, []);
        found.get(label)!.push(col);
        break;
      }
    }
  }
  return Array.from(found.entries()).map(([label, cols]) => {
    const hint = NUMERIC_TEXT_PATTERNS.find(p => p.label === label)!.hint;
    return `${cols.length === 1 ? 'Column' : 'Columns'} ${cols.map(c => `"${c}"`).join(', ')} look${cols.length === 1 ? 's' : ''} like numbers written with ${label}, so ${cols.length === 1 ? 'it was' : 'they were'} read as text and cannot be plotted. ${hint}`;
  });
};

// All-numeric header names almost always mean the file has no header row, in
// which case the first observation has been consumed as column names.
const looksHeaderless = (columns: string[]) =>
  columns.length >= 2 && columns.every(c => c.trim() !== '' && Number.isFinite(Number(c)));

// Exported for tests: all the warning logic is pure, and keeping it separate
// from File plumbing means it can be exercised on a string. (PapaParse reaches
// for FileReaderSync when handed a File, which only exists in a Worker.)
//
// Reading the file to text first costs nothing: with no `chunk`/`step` config
// PapaParse's own FileReader path already materialises the whole file as a
// single string before parsing, so peak memory is unchanged.
export const parseCSVText = (text: string): ParsedTable => {
  const res = Papa.parse<Record<string, any>>(text, {
    header: true,
    dynamicTyping: true,
    skipEmptyLines: 'greedy',
  });

  const fields = res.meta.fields ?? [];
  const columns = fields.filter(c => c != null && c !== '');
  if (!columns.length) throw new Error('No columns found — is the first row a header?');

  const warnings: string[] = [];

  // Quote damage swallows everything after it, so say so before the user
  // wonders why the file lost 4,000 rows.
  const quoteErrors = res.errors.filter(e => e.type === 'Quotes');
  if (quoteErrors.length) {
    warnings.push(`Unclosed quotation mark near line ${(quoteErrors[0].row ?? 0) + 2}. Everything after it was read as a single value, so most of the file was probably not parsed. Check the quoting around that line.`);
  }

  // Ragged rows: extra cells are dropped (they land outside meta.fields),
  // missing cells become nulls. Both change the data silently.
  const tooMany = res.errors.filter(e => e.code === 'TooManyFields');
  const tooFew = res.errors.filter(e => e.code === 'TooFewFields');
  if (tooMany.length) {
    warnings.push(`${plural(tooMany.length, 'row')} had more values than the header has columns (line ${listRows(tooMany.map(e => e.row ?? 0))}); the extra values were discarded. This usually means an unquoted delimiter inside a value, or a title line above the header.`);
  }
  if (tooFew.length) {
    warnings.push(`${plural(tooFew.length, 'row')} had fewer values than the header has columns (line ${listRows(tooFew.map(e => e.row ?? 0))}); the missing values were read as blank.`);
  }

  if (res.errors.some(e => e.code === 'UndetectableDelimiter') && columns.length === 1) {
    warnings.push(`Only one column was found and the delimiter could not be detected. If this file is not single-column, it may use an unusual separator.`);
  }

  const dropped = fields.length - columns.length;
  if (dropped > 0) {
    warnings.push(`${plural(dropped, 'header cell was', 'header cells were')} blank, so ${dropped === 1 ? 'that column' : 'those columns'} ${dropped === 1 ? 'was' : 'were'} skipped.`);
  }

  // PapaParse reports its own renames, which is exactly what we need and is
  // reliable in a way that pattern-matching the result is not: a column
  // genuinely called "Q1_1" alongside "Q1" is ordinary in survey exports.
  // meta.renamedHeaders maps newName -> originalName.
  const renamed = Object.entries(res.meta.renamedHeaders ?? {});
  if (renamed.length) {
    warnings.push(`The header repeats ${Array.from(new Set(renamed.map(([, orig]) => `"${orig}"`))).join(', ')}. Repeated names were renamed (${renamed.map(([now, orig]) => `"${orig}" → "${now}"`).join(', ')}), so some columns are not named as they are in the file.`);
  }

  if (looksHeaderless(columns)) {
    warnings.push(`Every column name is a number (${columns.slice(0, 4).join(', ')}${columns.length > 4 ? ', …' : ''}), which usually means the file has no header row — in which case the first observation was used as the column names and is missing from the data.`);
  }

  const table = rowsToTable(res.data, columns);
  return { table, warnings: [...warnings, ...numericTextWarnings(table)] };
};

const parseCSV = async (file: File): Promise<ParsedTable> => parseCSVText(await file.text());

// C0 control characters, DEL, and the Unicode replacement character. None of
// these occur in a header a human typed, in any script — so they are the
// signature of bytes being read as text that were never text. Tab, newline and
// carriage return are deliberately excluded: Excel puts them in wrapped headers.
const BINARY_JUNK = /[\x00-\x08\x0B\x0C\x0E-\x1F\x7F\uFFFD]/;

// Everything below operates on the plain data the worker sends back, never on
// SheetJS objects — see xlsx.worker.ts for why that boundary exists. Split out
// as a pure function for the same reason parseCSVText is: the warnings are the
// part worth testing, and they should not need a Worker to exercise.
export const xlsxExtractToTable = (
  { sheetNames, sheetName, autoSelected, rows, columns: rawColumns }: WorkbookExtract,
): ParsedTable => {
  let columns = rawColumns;
  // SheetJS does not throw on a file that is not a spreadsheet: handed random
  // bytes it returns a plausible-looking workbook whose headers are binary
  // garbage. The failure then surfaced downstream as "needs at least two
  // numeric columns", which sends the user to check their data when the real
  // problem is that the file is corrupt, truncated, or not an XLSX at all.
  const junk = columns.filter(c => BINARY_JUNK.test(c));
  if (junk.length && junk.length >= columns.length / 2) {
    throw new Error(
      `"${sheetName}" does not contain readable spreadsheet data — most of its column names are binary rather than text. The file is probably corrupt, incompletely downloaded, or not really an XLSX. Try re-exporting it, or save it as CSV.`
    );
  }

  // A header cell holding an empty string (rather than being truly blank, which
  // SheetJS names __EMPTY) becomes a column called "". The CSV path has always
  // dropped those; the XLSX path kept them, producing an unnamed, unselectable
  // column in the Variables list (C8).
  const blankNamed = columns.filter(c => c.trim() === '');
  columns = columns.filter(c => c.trim() !== '');

  if (!columns.length) {
    // Naming the other sheets matters: a Readme-then-Data workbook is common,
    // and "This sheet is empty" alone sends the user looking in the wrong place.
    const others = sheetNames.filter(s => s !== sheetName);
    throw new Error(
      `Sheet "${sheetName}" is empty.${others.length ? ` This workbook also contains ${others.map(s => `"${s}"`).join(', ')} — pick one of those from the Sheet list, or save it as its own file.` : ''}`
    );
  }

  const warnings: string[] = [];
  if (sheetNames.length > 1) {
    // Say WHY this sheet, not just which: silently skipping past an empty first
    // sheet is helpful, and is exactly the kind of help that should be visible.
    const skipped = autoSelected && sheetName !== sheetNames[0];
    const lead = skipped
      ? `"${sheetNames[0]}" has no data rows, so "${sheetName}" was read instead`
      : `Only the "${sheetName}" sheet was read`;
    // Don't re-list a sheet the sentence has already named.
    const named = new Set([sheetName, ...(skipped ? [sheetNames[0]] : [])]);
    const others = sheetNames.filter(s => !named.has(s));
    warnings.push(
      `${lead}.${others.length ? ` This workbook also contains ${others.map(s => `"${s}"`).join(', ')}.` : ''} Use the Sheet list to read a different one.`,
    );
  }
  // Below the refusal threshold, say it rather than silently keeping a column
  // the user cannot match to anything in their sheet.
  if (junk.length) {
    warnings.push(`${plural(junk.length, 'column name')} contains characters that are not readable text, which usually means the header row was misread. Check that the columns line up with your sheet.`);
  }
  if (blankNamed.length) {
    warnings.push(`${plural(blankNamed.length, 'header cell was', 'header cells were')} blank, so ${blankNamed.length === 1 ? 'that column' : 'those columns'} ${blankNamed.length === 1 ? 'was' : 'were'} skipped.`);
  }
  // SheetJS invents __EMPTY / __EMPTY_1 keys for header cells that are blank,
  // which is the signature of a title line sitting above the real header.
  const empties = columns.filter(c => /^__EMPTY(_\d+)?$/.test(c));
  if (empties.length) {
    warnings.push(`${plural(empties.length, 'column')} had no header cell and ${empties.length === 1 ? 'was' : 'were'} named ${empties.slice(0, 3).map(c => `"${c}"`).join(', ')}. If the sheet has a title row above the header, the first data row is being used as the column names.`);
  }

  // Date cells survive the worker boundary as Date objects (structured clone
  // preserves them), and rowsToTable is about to render them as ISO strings —
  // so this is the last point at which they are identifiable. Worth saying:
  // reading them as text is a deliberate choice with a real cost, since a date
  // column can no longer go on an axis.
  const dateColumns = columns.filter(c => rows.some(r => r[c] instanceof Date));
  if (dateColumns.length) {
    warnings.push(`${dateColumns.length === 1 ? 'Column' : 'Columns'} ${dateColumns.slice(0, 3).map(c => `"${c}"`).join(', ')}${dateColumns.length > 3 ? ', …' : ''} ${dateColumns.length === 1 ? 'holds dates, which were' : 'hold dates, which were'} read as text (ISO 8601) rather than numbers, so ${dateColumns.length === 1 ? 'it cannot' : 'they cannot'} be plotted on an axis or entered into a PCA. Convert to a number — days since a start date, for instance — if you need to analyse by time.`);
  }

  const table = rowsToTable(rows, columns);
  return { table, warnings: [...warnings, ...numericTextWarnings(table)] };
};

// Parse the workbook in a worker and terminate it, so SheetJS never executes in
// the realm holding the assistant's API key. There is deliberately NO
// main-thread fallback: a silent one would drop the isolation exactly when the
// environment is unusual, which is the wrong direction to fail. Workers are more
// widely supported than the WebGL this app already requires, so a browser that
// cannot run one cannot run the app either.
const runXlsxWorker = async (file: File, req: Omit<XlsxRequest, 'buffer'>): Promise<WorkbookExtract> => {
  if (typeof Worker === 'undefined') {
    throw new Error('This browser cannot read XLSX files (no Web Worker support). Save the sheet as CSV instead.');
  }
  const worker = new Worker(new URL('./xlsx.worker.ts', import.meta.url), { type: 'module' });
  try {
    const buffer = await file.arrayBuffer();
    const res = await new Promise<XlsxResponse>((resolve, reject) => {
      worker.onmessage = (e: MessageEvent<XlsxResponse>) => resolve(e.data);
      // A worker that dies mid-parse resolves nothing; without this the caller
      // waits forever on a spinner rather than seeing the failure.
      worker.onerror = (e) => reject(new Error(e.message || 'The XLSX reader crashed.'));
      worker.onmessageerror = () => reject(new Error('The XLSX reader returned data that could not be read.'));
      worker.postMessage({ ...req, buffer } satisfies XlsxRequest, [buffer]);
    });
    if (!res.ok) throw new Error(res.error);
    return res.extract;
  } finally {
    worker.terminate();
  }
};

const parseXLSX = async (file: File, sheet?: string): Promise<ParsedTable> =>
  xlsxExtractToTable(await runXlsxWorker(file, { sheet }));

/**
 * Sheet names and sizes without converting any of them, for the picker. Costs
 * one workbook read; the dimensions come from each sheet's stored range.
 * Returns [] for anything that is not a workbook, so callers need no branch.
 */
export const listSheets = async (file: File): Promise<SheetInfo[]> => {
  if (!file.name.toLowerCase().endsWith('.xlsx')) return [];
  try {
    return (await runXlsxWorker(file, { namesOnly: true })).sheets;
  } catch {
    // A corrupt file still has to reach the user through the normal parse path,
    // where the error message is specific. Failing the peek silently avoids
    // reporting it twice, in two different voices.
    return [];
  }
};

const parseParquet = async (file: File): Promise<ParsedTable> => {
  const { parquetReadObjects } = await import('hyparquet');
  const rows = await parquetReadObjects({ file: await file.arrayBuffer() });
  if (!rows.length) throw new Error('Parquet file has no rows');
  const columns = Object.keys(rows[0]);
  // Straight to rowsToTable, which sanitizes every cell anyway. The mapped copy
  // this replaces kept the original rows, a second full set of row objects and
  // the columnar result all alive at peak — measured +314 MB for the copy alone
  // — and ran sanitizeCell twice per cell (F20). BigInt now lives in
  // sanitizeCell, so nothing is lost by removing the pass.
  return { table: rowsToTable(rows, columns), warnings: [] };
};

export const readTable = async (file: File, opts: { sheet?: string } = {}): Promise<ParsedTable> => {
  const name = file.name.toLowerCase();
  // Size is checked before the extension so an oversized file gets the useful
  // message rather than a complaint about its suffix.
  if (file.size > MAX_FILE_BYTES) {
    throw new Error(
      `"${file.name}" is ${formatBytes(file.size)}, over the ${formatBytes(MAX_FILE_BYTES)} limit. Everything here runs in the browser tab, which cannot hold a table that size alongside the plot. Filter or subsample the file first, or split it by group.`,
    );
  }

  const read = async (): Promise<ParsedTable> => {
    if (name.endsWith('.csv')) return parseCSV(file);
    if (name.endsWith('.xlsx')) return parseXLSX(file, opts.sheet);
    if (name.endsWith('.parquet')) return parseParquet(file);
    throw new Error(`Unsupported file type — use one of: ${SUPPORTED_EXTENSIONS.join(', ')}`);
  };

  const parsed = await read();

  // Sentinel-code detection deliberately does NOT run here (it used to — A14).
  // Scanning every column during import was measurable latency on wide survey
  // tables, and a warning nobody can act on is only half a feature. Instead the
  // app asks after every upload whether to scan, and the Missing-value-codes
  // dialog runs the detector on demand and lets the user act on what it finds.
  // Said afterwards on purpose: it explains a wait the user has just sat
  // through, and warns them off the interactions that will be slow next.
  if (file.size > LARGE_FILE_BYTES) {
    return {
      ...parsed,
      warnings: [
        ...parsed.warnings,
        `This file is ${formatBytes(file.size)}. Everything runs in the browser, so rotating, clustering and the k/eps diagnostics will be noticeably slower than usual, and the tab may stop responding while they run.`,
      ],
    };
  }
  return parsed;
};

import { DataTable, asNumber, median, numericValues } from './table';

// In-browser PCA: median imputation → (optional) standardization → covariance/
// correlation matrix → Jacobi eigendecomposition → scores + loadings.
// Equivalent to sklearn's PCA on standardized data, up to component sign;
// signs are fixed so each component's largest-|loading| variable is positive.

export type PCAResult = {
  table: DataTable;                       // input table + score columns (see `columns`)
  columns: string[];                      // names of the score columns this run added
  replaced: string[];                     // columns of a previous same-label run this one replaced
  label: string;                          // sanitized run label ('' = the unnamed run)
  loadings: Record<string, { var: string; loading: number }[]>; // per score column, sorted by |loading|
  varianceExplained: number[];            // fraction per KEPT component
  /** Variance fraction for every component, kept or not — the full scree (B4). */
  spectrum: number[];
  /** Eigenvalues for every component, for the Kaiser > 1 rule (B4). */
  eigenvalues: number[];
  cumulative: number[];
  variables: string[];
  k: number;
  /**
   * What happened to the incomplete rows. Reported because both strategies
   * change the answer: median imputation shrinks variance and attenuates
   * correlations in proportion to how much was filled in, while complete-case
   * changes n and can bias the sample if missingness is not random.
   * "we impute" is a disclaimer; "we imputed 47 of 1,800 cells" is a disclosure
   * the reader can act on.
   */
  missing: MissingReport;
};

export type MissingStrategy = 'median' | 'complete' | 'iterative';

export type MissingReport = {
  strategy: MissingStrategy;
  /** Cells filled in (median or iterative PCA). Always 0 under complete-case. */
  imputedCells: number;
  totalCells: number;
  /** Rows missing at least one value, per variable, worst first. */
  byVariable: { var: string; n: number }[];
  /** Rows the decomposition actually used. */
  rowsUsed: number;
  /** Rows excluded for having any gap. Only non-zero under complete-case. */
  rowsDropped: number;
  /** Iterative imputation only: how long it ran and whether it settled. */
  iterations?: number;
  converged?: boolean;
};

/**
 * Is this column a PCA score column?
 *
 * One predicate, because there were three and they disagreed: case-sensitive
 * `/^PC\d+(_|$)/` in the PCA panel, case-INsensitive in `suggestStandardize`,
 * and an exact `['PC1','PC2','PC3']` membership test in `pickDefaultAxes`. A
 * file with lowercase `pc1`/`pc2` was therefore treated as PC scores by the
 * clustering heuristic (standardize off) while simultaneously being offered as
 * raw PCA input by the panel (finding E2).
 *
 * Case-insensitive is the right resolution: a components file written by R or
 * SPSS may use either case, and nothing downstream cares which.
 */
export const isPCColumn = (name: string): boolean => /^PC\d+(_|$)/i.test(name);

/** The bare PC1..PC3 a components-file projection creates, in order. */
export const BASE_PC_COLUMNS = ['PC1', 'PC2', 'PC3'];

// Run labels become column-name fragments — keep them word-shaped
export const sanitizeLabel = (s: string): string =>
  s.trim().replace(/\s+/g, '_').replace(/[^\w-]/g, '_').replace(/_+/g, '_').replace(/^_+|_+$/g, '');

// Suggest a run label from the selected variable names: the shared prefix or
// suffix once counters are stripped (openness_1..openness_5 → "openness",
// Q1_Need..Q5_Need → "Need"). Returns null when nothing at least two
// characters long is shared — mixed subsets (O1..O5 + N1..N5) on purpose
// yield null so the user (or the assistant) names the run deliberately.
export const deriveRunLabel = (names: string[]): string | null => {
  if (names.length < 2) return null;
  const shared = (get: (s: string, i: number) => string, len: (s: string) => number) => {
    let n = Math.min(...names.map(len));
    let out = '';
    for (let i = 0; i < n; i++) {
      const ch = get(names[0], i);
      if (!names.every(nm => get(nm, i) === ch)) break;
      out += ch;
    }
    return out;
  };
  const prefix = shared((s, i) => s[i], s => s.length).replace(/[\d_\-\s]+$/g, '');
  const suffix = shared((s, i) => s[s.length - 1 - i], s => s.length)
    .split('').reverse().join('').replace(/^[\d_\-\s]+/g, '');
  const best = (suffix.length > prefix.length ? suffix : prefix);
  const clean = sanitizeLabel(best);
  return clean.length >= 2 ? clean : null;
};

// The column names a run owns: COMP_<label> for a single kept component (a
// composite score), PC1_<label>.. for a labeled set, bare PC1.. when unnamed.
export const pcaColumnNames = (label: string, k: number): string[] => {
  if (label && k === 1) return [`COMP_${label}`];
  return Array.from({ length: k }, (_, c) => (label ? `PC${c + 1}_${label}` : `PC${c + 1}`));
};

// Which existing columns a (re-)run of `label` replaces. Covers both shapes
// (COMP_x and PCn_x) so relabeling k between runs never strands columns.
const ownedByLabel = (label: string) => {
  const esc = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return label
    ? new RegExp(`^(PC\\d+_${esc}|COMP_${esc})$`)
    : /^PC\d+$/;
};

// Jacobi eigenvalue iteration for symmetric matrices. Rock-solid for the
// p×p (p ≤ ~200) matrices survey data produces.
const jacobiEigen = (A: number[][]): { values: number[]; vectors: number[][] } => {
  const n = A.length;
  const a = A.map(row => row.slice());
  // V starts as identity; columns accumulate the eigenvectors
  const V: number[][] = Array.from({ length: n }, (_, i) =>
    Array.from({ length: n }, (_, j) => (i === j ? 1 : 0)));

  // Convergence is measured RELATIVE to the matrix's own scale. The absolute
  // `sqrt(off) < 1e-12` this replaces is unreachable for a covariance PCA on
  // large-magnitude columns — income in dollars, reaction times in
  // milliseconds — so those runs burned all 100 sweeps every time, which at
  // p ≈ 200 is on the order of 10⁹ operations on the main thread for a result
  // that had converged in a handful (finding A13). Results were correct, just
  // paid for many times over.
  let scale = 0;
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) scale += a[i][j] * a[i][j];
  const tolerance = Math.max(Math.sqrt(scale) * 1e-14, Number.MIN_VALUE);

  for (let sweep = 0; sweep < 100; sweep++) {
    let off = 0;
    for (let i = 0; i < n; i++)
      for (let j = i + 1; j < n; j++) off += a[i][j] * a[i][j];
    if (Math.sqrt(off) <= tolerance) break;

    for (let p = 0; p < n - 1; p++) {
      for (let q = p + 1; q < n; q++) {
        if (Math.abs(a[p][q]) < 1e-15) continue;
        const theta = (a[q][q] - a[p][p]) / (2 * a[p][q]);
        const t = Math.sign(theta || 1) / (Math.abs(theta) + Math.sqrt(theta * theta + 1));
        const c = 1 / Math.sqrt(t * t + 1);
        const s = t * c;
        for (let k = 0; k < n; k++) {
          const akp = a[k][p], akq = a[k][q];
          a[k][p] = c * akp - s * akq;
          a[k][q] = s * akp + c * akq;
        }
        for (let k = 0; k < n; k++) {
          const apk = a[p][k], aqk = a[q][k];
          a[p][k] = c * apk - s * aqk;
          a[q][k] = s * apk + c * aqk;
        }
        for (let k = 0; k < n; k++) {
          const vkp = V[k][p], vkq = V[k][q];
          V[k][p] = c * vkp - s * vkq;
          V[k][q] = s * vkp + c * vkq;
        }
      }
    }
  }

  // sort by eigenvalue descending
  const order = Array.from({ length: n }, (_, i) => i)
    .sort((i, j) => a[j][j] - a[i][i]);
  return {
    values: order.map(i => a[i][i]),
    vectors: order.map(i => V.map(row => row[i])), // vectors[c] = c-th eigenvector
  };
};

// Regularized iterative PCA imputation (Josse & Husson 2012; the method behind
// R's missMDA::imputePCA). Where median imputation ignores the correlation
// structure entirely — it fills every gap in a variable with the same number —
// this reconstructs each missing cell from the low-rank structure of the other
// variables, iterating until the fill stops moving:
//
//   1. start from the column mean
//   2. PCA the completed matrix, keep `rank` components
//   3. rebuild the matrix from those components
//   4. overwrite ONLY the missing cells with the rebuilt values; observed data
//      is never altered
//   5. repeat from 2 until the imputed values stop changing
//
// The regularization matters and is not optional: plain iterative PCA fits the
// noise in the observed cells and drifts, especially with many components or
// heavy missingness. Each component's contribution is shrunk by
// (lambda_s - sigma^2)/lambda_s, where sigma^2 is the mean of the discarded
// eigenvalues — an estimate of residual noise. A component barely above the
// noise floor is therefore damped towards zero rather than trusted.
//
// Honest limits, restated for the user in disclosures.ts: `rank` is taken from
// the number of components being kept rather than chosen by cross-validation
// (missMDA's estim_ncpPCA), and this is single imputation, so downstream
// results ignore the uncertainty in the filled values and standard errors are
// optimistic. It is a better point estimate, not a substitute for a model of
// the missingness.
export const imputeIterativePCA = (
  cols: (number | null)[][],
  opts: { rank?: number; standardize?: boolean; maxIter?: number; tol?: number } = {},
): { columns: number[][]; iterations: number; converged: boolean; rank: number } => {
  const p = cols.length;
  const n = cols[0]?.length ?? 0;
  const standardize = opts.standardize ?? true;
  const maxIter = opts.maxIter ?? 200;
  const tol = opts.tol ?? 1e-8;
  // At least one discarded component is required, or sigma^2 has nothing to
  // estimate from and the fit is unregularized.
  const rank = Math.max(1, Math.min(opts.rank ?? 2, p - 1));

  const observed: boolean[][] = cols.map(c =>
    Array.from({ length: n }, (_, i) => typeof c[i] === 'number' && Number.isFinite(c[i] as number)));

  // Start from the column mean of the observed values.
  const X: number[][] = Array.from({ length: n }, () => new Array(p).fill(0));
  for (let j = 0; j < p; j++) {
    let sum = 0, cnt = 0;
    for (let i = 0; i < n; i++) if (observed[j][i]) { sum += cols[j][i] as number; cnt++; }
    const mean0 = cnt ? sum / cnt : 0;
    for (let i = 0; i < n; i++) X[i][j] = observed[j][i] ? (cols[j][i] as number) : mean0;
  }

  const anyMissing = observed.some(c => c.some(o => !o));
  if (!anyMissing || n < 3) return { columns: transpose(X, n, p), iterations: 0, converged: true, rank };

  let iterations = 0, converged = false;
  for (let it = 1; it <= maxIter; it++) {
    iterations = it;
    // Centre and (optionally) scale using the CURRENT completed matrix — the
    // moments move as the fill changes, which is why this is inside the loop.
    const mu = new Array(p).fill(0), sd = new Array(p).fill(1);
    for (let j = 0; j < p; j++) {
      let sum = 0;
      for (let i = 0; i < n; i++) sum += X[i][j];
      mu[j] = sum / n;
      let sq = 0;
      for (let i = 0; i < n; i++) sq += (X[i][j] - mu[j]) ** 2;
      const s = Math.sqrt(sq / n);
      sd[j] = standardize ? (s || 1) : 1;
    }
    const Z: number[][] = Array.from({ length: n }, (_, i) =>
      Array.from({ length: p }, (_, j) => (X[i][j] - mu[j]) / sd[j]));

    const C: number[][] = Array.from({ length: p }, () => new Array(p).fill(0));
    for (let a = 0; a < p; a++) {
      for (let b = a; b < p; b++) {
        let acc = 0;
        for (let i = 0; i < n; i++) acc += Z[i][a] * Z[i][b];
        C[a][b] = C[b][a] = acc / n;
      }
    }
    const { values, vectors } = jacobiEigen(C);

    // sigma^2: mean of the eigenvalues we are throwing away = residual noise.
    let tail = 0;
    for (let s = rank; s < p; s++) tail += Math.max(values[s], 0);
    const sigma2 = tail / (p - rank);

    // Rank-`rank` reconstruction with each component shrunk toward zero in
    // proportion to how close its eigenvalue sits to the noise floor.
    const recon: number[][] = Array.from({ length: n }, () => new Array(p).fill(0));
    for (let s = 0; s < rank; s++) {
      const lam = Math.max(values[s], 0);
      const shrink = lam > 0 ? Math.max(0, (lam - sigma2) / lam) : 0;
      if (shrink === 0) continue;
      const v = vectors[s];
      for (let i = 0; i < n; i++) {
        let score = 0;
        for (let j = 0; j < p; j++) score += Z[i][j] * v[j];
        const f = score * shrink;
        for (let j = 0; j < p; j++) recon[i][j] += f * v[j];
      }
    }

    // Replace ONLY the missing cells; observed values are never touched.
    let delta = 0, scale = 0;
    for (let j = 0; j < p; j++) {
      for (let i = 0; i < n; i++) {
        if (observed[j][i]) continue;
        const next = recon[i][j] * sd[j] + mu[j];
        delta += (next - X[i][j]) ** 2;
        scale += next ** 2;
        X[i][j] = next;
      }
    }
    if (delta <= tol * Math.max(scale, 1e-12)) { converged = true; break; }
  }

  return { columns: transpose(X, n, p), iterations, converged, rank };
};

const transpose = (X: number[][], n: number, p: number): number[][] =>
  Array.from({ length: p }, (_, j) => Array.from({ length: n }, (_, i) => X[i][j]));

export const runPCA = (
  table: DataTable,
  variables: string[],
  opts: { k?: number; standardize?: boolean; label?: string; missing?: MissingStrategy } = {},
): PCAResult => {
  const standardize = opts.standardize ?? true;
  const strategy: MissingStrategy = opts.missing ?? 'median';
  const label = sanitizeLabel(opts.label ?? '');
  const p = variables.length;
  if (p < 2) throw new Error('Pick at least two numeric variables for a PCA.');
  const n = table.nRows;
  if (n < 3) throw new Error('Too few rows for a PCA.');
  // k = 1 is legitimate: it keeps only the first component, the composite-score
  // workflow (run per item subset, keep the top PC of each as a named score).
  //
  // Clamped to the RANK, min(p, n-1), not just to p. With n = 3 and p = 5 the
  // covariance matrix has rank 2, so components 3 to 5 have numerically-zero
  // eigenvalues and their scores are floating-point noise — but they were
  // produced, plotted and reported with a variance-explained figure like any
  // other (finding A10).
  const maxRank = Math.max(1, Math.min(p, n - 1));
  const k = Math.max(1, Math.min(opts.k ?? 3, maxRank));

  // Coerce every selected variable once: null marks "not observed as a number",
  // which is what both strategies key off.
  const cols: (number | null)[][] = variables.map(v =>
    (table.data[v] ?? []).map(asNumber));
  const missingByVar: { var: string; n: number }[] = [];
  cols.forEach((col, j) => {
    const have = numericValues(col).length;
    if (have === 0) throw new Error(`"${variables[j]}" has no numeric values.`);
    // Rows past the end of a short column count as missing too.
    if (have < n) missingByVar.push({ var: variables[j], n: n - have });
  });

  // Which rows the decomposition runs on. Complete-case keeps only rows with no
  // gap in ANY selected variable, so adding a poorly-covered variable can drop a
  // lot of rows at once — hence rowsDropped is reported, not just inferred.
  // Iterative imputation reconstructs the gaps from the low-rank structure
  // before any of the decomposition below runs; it fills every row, so the row
  // set is the same as median's.
  const iterative = strategy === 'iterative'
    ? imputeIterativePCA(cols, { rank: k, standardize })
    : null;

  const rows: number[] = [];
  for (let i = 0; i < n; i++) {
    if (strategy !== 'complete' || cols.every(c => typeof c[i] === 'number')) rows.push(i);
  }
  if (strategy === 'complete' && rows.length < 3) {
    throw new Error(
      `Complete-case analysis leaves only ${rows.length} row${rows.length === 1 ? '' : 's'} with no missing values across these ${p} variables — too few for a PCA. Use median imputation, or drop the variables with the most missing data.`
    );
  }
  const m = rows.length;

  // centre, optionally scale (population sd, sklearn-style)
  const X: number[][] = Array.from({ length: m }, () => new Array(p));
  for (let j = 0; j < p; j++) {
    const col = cols[j];
    // Under complete-case the median is never consulted; under imputation it is
    // computed from the observed values only, which is the standard definition.
    const med = median(numericValues(col));
    const filled = iterative?.columns[j];
    let sum = 0;
    for (let r = 0; r < m; r++) {
      const v = filled ? filled[rows[r]] : (col[rows[r]] ?? med);
      X[r][j] = v;
      sum += v;
    }
    const mean = sum / m;
    let sq = 0;
    for (let r = 0; r < m; r++) sq += (X[r][j] - mean) ** 2;
    const sd = Math.sqrt(sq / m);
    if (standardize && sd === 0) throw new Error(`"${variables[j]}" is constant${strategy === 'complete' ? ' across the complete cases' : ''} — drop it or turn off standardization.`);
    const div = standardize ? sd : 1;
    for (let r = 0; r < m; r++) X[r][j] = (X[r][j] - mean) / div;
  }

  // covariance (= correlation when standardized) matrix
  const C: number[][] = Array.from({ length: p }, () => new Array(p).fill(0));
  for (let i = 0; i < p; i++) {
    for (let j = i; j < p; j++) {
      let s = 0;
      for (let r = 0; r < m; r++) s += X[r][i] * X[r][j];
      C[i][j] = C[j][i] = s / m;
    }
  }

  const { values, vectors } = jacobiEigen(C);
  const total = values.reduce((s, v) => s + Math.max(v, 0), 0) || 1;

  // deterministic signs: largest-|loading| variable positive per component
  const comps = vectors.slice(0, k).map(vec => {
    let maxIdx = 0;
    for (let j = 1; j < p; j++) if (Math.abs(vec[j]) > Math.abs(vec[maxIdx])) maxIdx = j;
    return vec[maxIdx] < 0 ? vec.map(v => -v) : vec;
  });

  // scores: X̃ · component, written back at the ORIGINAL row positions so the
  // columnar table keeps its shape. Rows excluded by complete-case get null
  // rather than a fabricated score — they are genuinely unscored.
  const scoreCols: (number | null)[][] = comps.map(vec => {
    const col = new Array<number | null>(n).fill(null);
    for (let r = 0; r < m; r++) {
      let s = 0;
      for (let j = 0; j < p; j++) s += X[r][j] * vec[j];
      col[rows[r]] = s;
    }
    return col;
  });

  // Replacement is scoped to THIS run's identity: a re-run of "openness"
  // replaces only the openness columns; other labeled runs and the bare
  // PC1..PCk set coexist untouched. (Replacing everything matching ^PC\d+$
  // was the old behavior, and it silently ate earlier subset runs.)
  const owned = ownedByLabel(label);
  const pcNames = pcaColumnNames(label, k);
  const replaced = table.columns.filter(c => owned.test(c));
  const newTable: DataTable = {
    columns: [...table.columns.filter(c => !owned.test(c)), ...pcNames],
    data: {
      ...Object.fromEntries(Object.entries(table.data).filter(([c]) => !owned.test(c))),
      ...Object.fromEntries(pcNames.map((name, c) => [name, scoreCols[c]])),
    },
    nRows: n,
  };

  const loadings: PCAResult['loadings'] = {};
  comps.forEach((vec, c) => {
    loadings[pcNames[c]] = variables
      .map((v, j) => ({ var: v, loading: Math.round(vec[j] * 1000) / 1000 }))
      .sort((a, b) => Math.abs(b.loading) - Math.abs(a.loading));
  });

  const varianceExplained = values.slice(0, k).map(v => Math.max(v, 0) / total);
  // The FULL spectrum, not just the kept components (finding B4). The scree
  // chart plotted varianceExplained, whose length is k — so keeping 3
  // components drew 3 bars. But methods.ts teaches the Cattell scree test and
  // the Kaiser eigenvalue > 1 rule, and both need every eigenvalue: the elbow
  // is invisible if the plot stops at the elbow.
  const spectrum = values.map(v => Math.max(v, 0) / total);
  // Eigenvalues themselves, for the Kaiser criterion. On a correlation PCA each
  // variable contributes 1, so "> 1" is the meaningful line; on a covariance
  // PCA it is not, which is why the UI only draws it when standardized.
  const eigenvalues = values.map(v => Math.max(v, 0));
  const cumulative = varianceExplained.reduce<number[]>((acc, v) => {
    acc.push((acc[acc.length - 1] ?? 0) + v);
    return acc;
  }, []);

  const byVariable = missingByVar.sort((a, b) => b.n - a.n);
  const missing: MissingReport = {
    strategy,
    imputedCells: strategy === 'complete' ? 0 : byVariable.reduce((s, v) => s + v.n, 0),
    totalCells: n * p,
    byVariable,
    rowsUsed: m,
    rowsDropped: n - m,
    ...(iterative ? { iterations: iterative.iterations, converged: iterative.converged } : {}),
  };

  return { table: newTable, columns: pcNames, replaced, label, loadings, varianceExplained, spectrum, eigenvalues, cumulative, variables, k, missing };
};

// Columnar table shared across the app: one array per column.
// Cells are number | string | null — null covers empty, NaN, and ±Infinity,
// mirroring how the old pandas backend serialized missing values.
export type DataTable = { columns: string[]; data: Record<string, any[]>; nRows: number };

export const sanitizeCell = (v: any): number | string | null => {
  if (v == null || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  if (typeof v === 'boolean') return v ? 1 : 0;
  // hyparquet returns BigInt for int64 columns. Handling it here rather than in
  // parseParquet lets that function pass rows straight to rowsToTable instead of
  // building a second full copy first (finding F20) — and closes the hole where
  // the old BigInt branch bypassed the finite check above entirely.
  if (typeof v === 'bigint') {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  }
  if (v instanceof Date) return v.toISOString();
  const s = String(v).trim();
  return s === '' ? null : s;
};

// Rows-of-objects (as parsers emit) → columnar table
export const rowsToTable = (rows: Record<string, any>[], columns: string[]): DataTable => {
  const data: Record<string, any[]> = {};
  for (const c of columns) data[c] = new Array(rows.length);
  for (let i = 0; i < rows.length; i++) {
    for (const c of columns) data[c][i] = sanitizeCell(rows[i][c]);
  }
  return { columns, data, nRows: rows.length };
};

/**
 * The app's single answer to "is this cell a number, and which one".
 *
 * Excel columns formatted as Text arrive as strings, and so do CSV values
 * PapaParse declined to convert. `pca.ts` and `engine.ts` already coerced them;
 * `numericColumns`, `numericPairs` and the clustering imputer did not, so the
 * same column was a usable measurement in one half of the app and missing data
 * in the other (finding C6). Worst case, clustering median-imputed *every* row
 * of a text-formatted column and silently clustered on the median.
 *
 * A finite number written as text is a number. Anything else — blank, NaN,
 * ±Infinity, a word — is null, meaning "not observed as a number".
 */
export const asNumber = (v: unknown): number | null => {
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  if (typeof v === 'string') {
    const s = v.trim();
    // Number('') is 0 and Number(' ') is 0, so the emptiness check must come first.
    if (s === '') return null;
    const n = Number(s);
    return Number.isFinite(n) ? n : null;
  }
  return null;
};

/** True when the column holds at least one value usable as a number. */
export const isNumericColumn = (vals: unknown[]): boolean => vals.some(v => asNumber(v) !== null);

export const numericValues = (vals: any[]): number[] =>
  vals.filter((v): v is number => typeof v === 'number');

export const median = (vals: number[]): number => {
  if (vals.length === 0) return 0;
  const s = [...vals].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
};

// Workspace persistence in IndexedDB (localStorage tops out ~5MB; snapshots
// with embedded tables can exceed that easily). Same four operations the old
// backend REST endpoints exposed, plus file export/import for sharing.

import { validateEfaState } from './efa/persistence';
export type WorkspaceMeta = { name: string; saved_at: string; bytes: number };

const DB_NAME = 'scatter-lab';
const STORE = 'workspaces';
// v2 adds the session store: the continuously-autosaved "where you left off"
// record, kept apart from named workspaces so autosave can never overwrite a
// deliberate checkpoint.
const SESSION_STORE = 'session';
const DB_VERSION = 2;

const openDB = (): Promise<IDBDatabase> =>
  new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = () => {
      if (!req.result.objectStoreNames.contains(STORE)) req.result.createObjectStore(STORE);
      if (!req.result.objectStoreNames.contains(SESSION_STORE)) req.result.createObjectStore(SESSION_STORE);
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });

const tx = async <T>(store: string, mode: IDBTransactionMode, fn: (store: IDBObjectStore) => IDBRequest<T>): Promise<T> => {
  const db = await openDB();
  return new Promise<T>((resolve, reject) => {
    const t = db.transaction(store, mode);
    const req = fn(t.objectStore(store));
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
    t.oncomplete = () => db.close();
  });
};

type Stored = { payload: any; saved_at: string; bytes: number };

export const listWorkspaces = async (): Promise<WorkspaceMeta[]> => {
  const [keys, values] = await Promise.all([
    tx<IDBValidKey[]>(STORE, 'readonly', s => s.getAllKeys()),
    tx<Stored[]>(STORE, 'readonly', s => s.getAll()),
  ]);
  return keys
    .map((k, i) => ({ name: String(k), saved_at: values[i]?.saved_at ?? '', bytes: values[i]?.bytes ?? 0 }))
    .sort((a, b) => b.saved_at.localeCompare(a.saved_at));
};

/**
 * Approximate the stored size from the table dimensions instead of serialising
 * the payload to measure it (finding F21).
 *
 * `bytes` is display-only — it renders as "12.4 MB" beside the workspace name —
 * and buying it with a full JSON.stringify meant every save serialised the whole
 * payload twice: once to measure, once again when IndexedDB structured-cloned
 * it. On a 200k × 30 table that measured 510 ms to stringify a 38.6 MB string
 * plus 1,080 ms to clone: about 1.6 s of blocked main thread and +77 MB
 * transient, for a number nothing reads back.
 *
 * The estimate walks only the table shapes, not the cells. Roughly 12 bytes per
 * cell is what mixed numeric/short-string JSON averages; being off by a third on
 * a label is immaterial, and it is honest about being an estimate.
 */
const estimateBytes = (payload: unknown): number => {
  const p = payload as { tables?: Record<string, { columns?: unknown[]; nRows?: number }> };
  let cells = 0;
  for (const t of Object.values(p?.tables ?? {})) {
    cells += (t?.columns?.length ?? 0) * (t?.nRows ?? 0);
  }
  // 2 KB covers the settings, notes and axis labels riding alongside.
  return cells * 12 + 2048;
};

export const saveWorkspace = async (name: string, payload: any): Promise<void> => {
  const stored: Stored = { payload, saved_at: new Date().toISOString().slice(0, 19), bytes: estimateBytes(payload) };
  await tx(STORE, 'readwrite', s => s.put(stored, name));
};

export const loadWorkspace = async (name: string): Promise<any | null> => {
  const stored = await tx<Stored | undefined>(STORE, 'readonly', s => s.get(name));
  return stored?.payload ?? null;
};

export const deleteWorkspace = async (name: string): Promise<void> => {
  await tx(STORE, 'readwrite', s => s.delete(name));
};

// --- session continuity ------------------------------------------------------
// One record, autosaved as the user works, restored on the next load. Same
// payload shape as a workspace so validateWorkspace/applyWorkspace cover both.

const SESSION_KEY = 'current';

export const saveSession = async (payload: unknown): Promise<void> => {
  await tx(SESSION_STORE, 'readwrite', s => s.put({ payload, saved_at: new Date().toISOString().slice(0, 19) }, SESSION_KEY));
};

export const loadSession = async (): Promise<unknown> => {
  const stored = await tx<{ payload: unknown } | undefined>(SESSION_STORE, 'readonly', s => s.get(SESSION_KEY));
  return stored?.payload ?? null;
};

export const clearSession = async (): Promise<void> => {
  await tx(SESSION_STORE, 'readwrite', s => s.delete(SESSION_KEY));
};

export const exportWorkspaceFile = (name: string, payload: any) => {
  const blob = new Blob([JSON.stringify({ name, ...payload })], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `${name}.scatterlab.json`;
  a.click();
  URL.revokeObjectURL(a.href);
};

/** The payload shape this build knows how to apply. */
export const WORKSPACE_VERSION = 2;

// `unknown` rather than `any` throughout: this is the one place in the app that
// handles a value nobody typed, so the narrowing has to be real.
type Rec = Record<string, unknown>;
const isRecord = (v: unknown): v is Rec => !!v && typeof v === 'object' && !Array.isArray(v);

const isTable = (t: unknown): boolean => {
  if (!isRecord(t)) return false;
  return Array.isArray(t.columns)
    && t.columns.every((c: unknown) => typeof c === 'string')
    && isRecord(t.data)
    && typeof t.nRows === 'number' && Number.isFinite(t.nRows) && t.nRows >= 0;
};

/**
 * Reject a workspace this build cannot apply, with a reason.
 *
 * The check used to be `!parsed.version` and nothing else, so a truncated,
 * hand-edited or half-written file got as far as `applyWorkspace`, which
 * rehydrated a dangling table reference to `undefined` and left render to
 * dereference `d.table.nRows`. That threw inside React and white-screened the
 * app with no way back except a reload (finding C11). Everything below is
 * cheap; the point is that it happens BEFORE any state is replaced.
 */
export const validateWorkspace = (parsed: unknown): void => {
  if (!isRecord(parsed)) {
    throw new Error('Not a workspace file — expected a JSON object.');
  }
  if (typeof parsed.version !== 'number' || !Number.isFinite(parsed.version)) {
    throw new Error('Not a workspace file — it has no version number.');
  }
  // version is written on save and was never read back, so there was no
  // forward-compatibility story either. Now a newer file says so plainly
  // instead of failing somewhere further in.
  if (parsed.version > WORKSPACE_VERSION) {
    throw new Error(`This workspace was saved by a newer version of Scatter Lab (format ${parsed.version}, this build reads ${WORKSPACE_VERSION}).`);
  }

  if (parsed.tables != null && !isRecord(parsed.tables)) {
    throw new Error('Workspace file is damaged: its "tables" section is not an object.');
  }
  const tables: Rec = isRecord(parsed.tables) ? parsed.tables : {};
  for (const [id, t] of Object.entries(tables)) {
    if (!isTable(t)) throw new Error(`Workspace file is damaged: table "${id}" is not a valid table.`);
  }
  // A string is a reference into `tables`; anything else is an inline table.
  const resolve = (ref: unknown) => (typeof ref === 'string' ? tables[ref] : ref);

  if (parsed.datasets != null && !Array.isArray(parsed.datasets)) {
    throw new Error('Workspace file is damaged: its "datasets" section is not a list.');
  }
  // The failure that actually white-screened the app: a dataset naming a table
  // that is not in the file.
  (Array.isArray(parsed.datasets) ? parsed.datasets : []).forEach((d: unknown, i: number) => {
    if (!isRecord(d)) throw new Error(`Workspace file is damaged: dataset #${i + 1} is not an object.`);
    const where = typeof d.name === 'string' && d.name ? `"${d.name}"` : `#${i + 1}`;
    const t = resolve(d.table);
    if (t === undefined) {
      throw new Error(`Workspace file is damaged: dataset ${where} refers to a table ("${String(d.table)}") that the file does not contain.`);
    }
    if (!isTable(t)) throw new Error(`Workspace file is damaged: dataset ${where} has no usable table.`);
    validateEfaState(d.efa, (t as { nRows: number }).nRows);
  });

  if (parsed.pinnedViews != null && !Array.isArray(parsed.pinnedViews)) {
    throw new Error('Workspace file is damaged: its "pinnedViews" section is not a list.');
  }
  (Array.isArray(parsed.pinnedViews) ? parsed.pinnedViews : []).forEach((v: unknown, i: number) => {
    const t = isRecord(v) ? resolve(v.data) : undefined;
    if (t === undefined || !isTable(t)) {
      throw new Error(`Workspace file is damaged: pinned view #${i + 1} has no usable data.`);
    }
  });
};

// --- assistant conversation --------------------------------------------------
// Stored inside the workspace/session payload as an optional `conversation`
// section: the display transcript plus the wire-format history that lets the
// assistant actually continue where it left off (not just show old bubbles).
// The API key is NOT part of this — it stays in localStorage, as ever.

// `local` marks a message the panel composed rather than a model (the handoff
// greeting); it must survive a round-trip so restored greetings still aren't
// offered for thumbs feedback.
export type ConversationEntry = { kind: 'user' | 'assistant' | 'tool' | 'error'; text: string; local?: boolean };
export type Conversation = { entries: ConversationEntry[]; history: unknown[] };

const ENTRY_KINDS = new Set(['user', 'assistant', 'tool', 'error']);

/**
 * Reduce an untyped `conversation` section to something the panel can render,
 * or null if there is nothing usable. Unlike the table checks above this
 * sanitizes rather than throws: a workspace whose data is intact should not be
 * refused because its chat section is damaged — the chat is auxiliary.
 */
export const sanitizeConversation = (v: unknown): Conversation | null => {
  if (!isRecord(v)) return null;
  const entries = (Array.isArray(v.entries) ? v.entries : [])
    .filter((e: unknown): e is ConversationEntry =>
      isRecord(e) && typeof e.text === 'string' && typeof e.kind === 'string' && ENTRY_KINDS.has(e.kind));
  const history = (Array.isArray(v.history) ? v.history : []).filter(isRecord);
  if (entries.length === 0 && history.length === 0) return null;
  return { entries, history };
};

export const importWorkspaceFile = async (file: File): Promise<{ name: string; payload: unknown }> => {
  let parsed: unknown;
  try {
    parsed = JSON.parse(await file.text());
  } catch {
    // JSON.parse's own message ("Unexpected token < in JSON at position 0") is
    // not something to show a researcher who picked the wrong file.
    throw new Error('That file is not valid JSON, so it is not a workspace file.');
  }
  validateWorkspace(parsed);
  // validateWorkspace has established this is a record; narrow for the name.
  const rec = parsed as Rec;
  const name = typeof rec.name === 'string' && rec.name
    ? rec.name
    : file.name.replace(/\.scatterlab\.json$|\.json$/i, '');
  return { name, payload: parsed };
};
